import difflib, subprocess
print("# the map of unchanged lines, git show bce66f1fa:<chapter> to the tree, as difflib's equal blocks: base lines a-b -> tree lines c-d")
print("# regenerated in the repair round on the tree of the repair's specification commits (inference.tex and changes.tex changed; ranges.tex and basic-integers.tex as the first pass left them)")
for path in ['Specification/basic/inference.tex','Specification/basic/expressions/ranges.tex','Specification/basic-lib/basic-integers.tex','Specification/appendices/changes.tex']:
    old = subprocess.run(['git','show','bce66f1fa:'+path],capture_output=True,text=True).stdout.split('\n')
    new = open(path).read().split('\n')
    print('==', path)
    for tag,i1,i2,j1,j2 in difflib.SequenceMatcher(None,old,new,autojunk=False).get_opcodes():
        if tag=='equal': print(f'  {i1+1}-{i2} -> {j1+1}-{j2}')
        else: print(f'  {tag} base {i1+1}-{i2} tree {j1+1}-{j2}')
EOF
cat explorations/compile-ladder/rung-spec-inference/probes/reanchor/line-map.txt

